INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "梁进", "aliases": ["梁進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋沿河巡检使。944年四月丁未率乡社兵收复德州，《新五代史》也记其击败契丹、取回德州。尚无证据将他与梁进超合并。生卒年未载。", "biography": null, "status": "draft", "id": "2c3fc82d-242c-51a4-a4a4-4b2d3c96e653"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "高行周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：高行周。", "biography": null, "status": "draft", "id": "659c5f83-09bc-5282-8f02-4c7fa0a62729"}, {"name": "王周", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷262天复元年条所见人物：王周。", "biography": null, "status": "draft", "id": "dcf3a493-1cbc-5185-9787-8041333d1d90"}, {"name": "桑维翰", "aliases": ["桑維翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：桑维翰，主张自全、求援者。", "biography": null, "status": "draft", "id": "5132e50a-3ce2-55d5-8f89-fdccd6bf4f02"}, {"name": "景延广", "aliases": ["景延廣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：景延广，原客将、获任者。", "biography": null, "status": "draft", "id": "de8a964e-a028-50ee-8d54-2cbfda481e98"}, {"name": "卢亿", "aliases": ["盧億"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋河南留守判官，河南人。944年劝景延广停止借军费征收增加民众负担。《宋史》卢多逊传记载其父卢亿同一劝谏，补充其字子元。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "d3b0ddf3-5c3a-5f76-a1b6-4e1bc1edad9a"}, {"name": "安审信", "aliases": ["安審信"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安审信，西北先锋马军都指挥使、转投者。", "biography": null, "status": "draft", "id": "d2ddf941-57f6-5dc2-bf1b-d0256df4eae0"}, {"name": "张仁愿", "aliases": ["張仁願"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋大理卿，944年任征收民财的使者，前往兖州征钱十万缗，从安审信私藏中取钱完成征收。具体生卒年本段未载。", "biography": null, "status": "draft", "id": "91823b84-3cc0-53de-b432-7464f1e1784e"}, {"name": "李守贞", "aliases": ["李守貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内客省使。940年五月受命担任马全节讨伐李金全军队的都监，职务由《旧五代史》本纪补充。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a3d16959-684f-5c82-b848-8dcbdc73e85a"}, {"name": "杨檀", "aliases": ["楊檀", "杨光远", "楊光遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：杨檀，冀州刺史、反对遣归者。", "biography": null, "status": "draft", "id": "54ec3b10-aece-5189-91a8-84a03c5691a3"}, {"name": "潘环", "aliases": ["潘環", "潘瑰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：潘环，王村寨守将、奔梁者。", "biography": null, "status": "draft", "id": "5e093bc1-94d3-542b-ac05-e1f1184aa8ba"}, {"name": "张彦泽", "aliases": ["張彥澤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，938年任镇国军节度使，在华州截击并杀死东行的凤翔叛军。生卒年本段未载。", "biography": null, "status": "draft", "id": "194d0f9a-3b17-5635-9741-dffc983ee32e"}, {"name": "薛可言", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "堂阳人，后晋齐州防御使。944年拦截并击败援救青州的契丹军。生卒年本段未载。", "biography": null, "status": "draft", "id": "ed0108be-a16d-5939-897b-402f935485a3"}, {"name": "张从恩", "aliases": ["張從恩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，曾任澶州防御使。939年正月任后晋枢密副使。生卒年未载。", "biography": null, "status": "draft", "id": "e1e909ad-c88c-54a5-941c-6116c704a870"}, {"name": "赵延照", "aliases": ["趙延照"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "赵思温的儿子。《资治通鉴》记载，他在后晋任祁州刺史，并受父亲委托向石敬瑭转达幽州归附的请求。相关行动的具体年份未载。", "biography": null, "status": "draft", "id": "a3905a7c-cc29-5e76-a63f-eede596759ff"}, {"name": "皇甫遇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：皇甫遇，原严卫步军都指挥使、接侍卫步军者。", "biography": null, "status": "draft", "id": "0aa52fa6-cacc-5960-8646-9ab3a0393623"}, {"name": "符彦卿", "aliases": ["符彥卿", "李彦卿", "李彥卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：符彦卿，散员都指挥使、力战者。", "biography": null, "status": "draft", "id": "c837916f-0fdf-5954-a190-597b08cd9402"}, {"name": "朱文进", "aliases": ["硃文进", "朱文進", "硃文進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "永泰人，闽国拱宸军将领。《资治通鉴》记他与连重遇多次受王继鹏侮辱而心怀不满，《新五代史》还记二人因宸卫军待遇优厚而激怒部众。生卒年未载。", "biography": null, "status": "draft", "id": "309ef83c-46fe-51a1-86cc-c2cb8dc48d82"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "刘翰（淄州刺史）", "aliases": ["刘翰", "劉翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杨光远任命的淄州刺史，944年六月后晋军攻克淄州后被杀。《资治通鉴》记辛酉，《旧五代史》记辛丑朔，两书日期异说保留。与早期梁将刘捍分开。出生年未载。", "biography": null, "status": "draft", "id": "cdcc647a-76fa-5c98-8fb2-a12ee9f221c6"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "刘弘熙", "aliases": ["劉弘熙", "刘洪熙", "劉洪熙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘熙，获封王爵之子。", "biography": null, "status": "draft", "id": "b67079e8-6ec8-5150-9451-5b3ce7983fec"}, {"name": "刘弘弼", "aliases": ["劉弘弼", "刘洪弼", "劉洪弼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘弼，获封王爵之子。", "biography": null, "status": "draft", "id": "dcf1aa4f-270b-5fb0-bf60-4a3911672aad"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

